4.999641652601305e+00	-6.459053e+03
4.999741652601305e+00	-6.135630e+03
4.999841652601305e+00	-5.803489e+03
4.999941652601305e+00	-5.464095e+03
4.999990000000000e+00	-5.297602e+03
];
plot(data(:,2))
%% raw data
td1=0.88;
idx1 = data(:,1) > 0.10; 
t_raw = data(idx1,1)-0.10; % Time
i_raw = data(idx1,2); % Current
%% 2. Computation of the envelope of the stator current (Envelope Extraction)
% Use MATLAB-Funktion 'envelope' for Peak-Detektion
[i_upper, i_lower] = envelope(i_raw, 100, 'peaks'); 

% Computation of DC-Offsets 
i_dc_calc = (i_upper + i_lower) / 2;

% Computation of the AC Envelope (Peakvalue)
I_ac_peak_calc = i_upper - i_dc_calc;

% Convert to RMS Reactance norm
I_ac_calc = I_ac_peak_calc/ sqrt(2);

%% 3. Identification of Parameters (as before, now with extracted data)
% Steady state shortcurrent (Meanvalue at the end)

idx_steady = t_raw > (5 * td1); 
Ik = mean(I_ac_calc(idx_steady)); 
xd_calc = In / Ik;

% Transient range
I_trans_total = I_ac_calc - Ik;
idx_trans_window = (t_raw > 0.05) & (t_raw < 1); 
p_trans = polyfit(t_raw(idx_trans_window), log(I_trans_total(idx_trans_window)), 1);
Td_p_calc = -1 / p_trans(1);
Ik_p_minus_Ik = exp(p_trans(2));
Ik_p_calc = Ik_p_minus_Ik + Ik;
xd_p_calc = In / Ik_p_calc;

% Subtransient range
I_trans_model = Ik_p_minus_Ik * exp(-t_raw / Td_p_calc);
I_subtrans = I_ac_calc - Ik - I_trans_model;
idx_sub_window = (t_raw > 0) & (t_raw < 0.05); 
p_sub = polyfit(t_raw(idx_sub_window), log(I_subtrans(idx_sub_window)), 1);
Td_pp_calc = -1 / p_sub(1);
Ik_pp_minus_Ik_p = exp(p_sub(2));
Ik_pp_calc = Ik_pp_minus_Ik_p + Ik_p_calc;
xd_pp_calc = In / Ik_pp_calc;

%% 4. Visualizing: Signal and Envelope
figure('Color', 'w', 'Name', 'Visualizing Signal');
plot(t_raw, i_raw/In, 'Color', [0.7 0.7 0.7], 'DisplayName', 'raw signal i(t)');
hold on;
plot(t_raw, i_upper/In, 'r-', 'LineWidth', 1.5, 'DisplayName', 'upper envelope');
plot(t_raw, i_lower/In, 'b-', 'LineWidth', 1.5, 'DisplayName', 'lower envelope');
plot(t_raw, i_dc_calc/In, 'g--', 'LineWidth', 1.5, 'DisplayName', 'computed DC-Offset');
grid on; xlabel('time (s)'); ylabel('Current (p.u.)');
title('Envelopes used for eliminating the DC-part');
legend('Location', 'NE');

%% 5. Visualisierung 2: Logarithmische Extrapolationsgeraden
figure('Color', 'w', 'Name', 'Extrapolation', 'Position', [150, 150, 850, 550]);
semilogy(t_raw, I_ac_calc / In, 'k.', 'MarkerSize', 3, 'DisplayName', 'AC-Envelope (RMS)');
hold on;

% Zeitvektor für die Geraden-Plots (nur für den Anfangsbereich zur Übersicht)
t_plot = linspace(0, 0.6, 200)';

% A) Transiente Extrapolationsgerade (Bezug zur stationären Kennlinie)
% Mathematisch: ln(I_ac - Ik) = p_trans(1)*t + p_trans(2) -> I_gerade = exp(p_trans(1)*t + p_trans(2)) + Ik
I_trans_line = exp(p_trans(1) * t_plot + p_trans(2)) + Ik;
semilogy(t_plot, I_trans_line / In, 'b--', 'LineWidth', 2, ...
    'DisplayName', 'Transient linear line (I_k'' at t=0)');

% B) Subtransiente Extrapolationsgerade
% Mathematisch: ln(I_ac - Ik - I_trans_model) = p_sub(1)*t + p_sub(2)
% Um sie im selben Diagramm darzustellen, addieren wir die transienten/stationären Anteile wieder drauf:
I_subtrans_line = exp(p_sub(1) * t_plot + p_sub(2)) + (Ik_p_minus_Ik * exp(-t_plot / Td_p_calc)) + Ik;
semilogy(t_plot, I_subtrans_line / In, 'r-.', 'LineWidth', 1, ...
    'DisplayName', 'Subtransient curve/line (for I_k'''' at t=0)');

% Punkte bei t=0 markieren
semilogy(0, Ik_p_calc/In, 'bo', 'MarkerFaceColor', 'b', 'MarkerSize', 8, 'DisplayName', 'I_k'' (p.u.)');
semilogy(0, Ik_pp_calc/In, 'ro', 'MarkerFaceColor', 'r', 'MarkerSize', 8, 'DisplayName', 'I_k'''' (p.u.)');
semilogy(0, Ik/In, 'go', 'MarkerFaceColor', 'g', 'MarkerSize', 8, 'DisplayName', 'I_k (p.u.)');

% Formatierung
grid on; ax = gca; ax.GridLineStyle = ':';
xlim([0 0.6]); ylim([0.3 20]);
xlabel('time t (s)'); ylabel('RMS Strom I_{AC} (p.u.) [log]');
title('Transiente & Subtransient extrapolation');
legend('Location', 'NE');

% Ergebnisse anzeigen
fprintf('=== Computed reactances ===\nxd   = %.3f p.u.\nxd''  = %.3f p.u.\nxd'''' = %.3f p.u.\n', xd_calc, xd_p_calc, xd_pp_calc);
fprintf('\n=== Time Constants ===\n');
fprintf('Transient  Td''  = %.4f s\n', Td_p_calc);
fprintf('Subtransient Td'''' = %.4f s\n', Td_pp_calc);
fprintf('\n=== Computed short circuit currents ===\n');
fprintf('Final  Ik  = %.4f A\n', Ik);
fprintf('Transient  Ik''  = %.4f A\n', Ik_p_calc);
fprintf('Subtransient Ik'''' = %.4f A\n', Ik_pp_calc);